CREATE OR REPLACE VIEW lr_serverless_aws_us_catalog.bricksurance_delegated_authority.da_metrics
COMMENT 'Delegated-authority oversight KPIs over bordereau submissions - outstanding files, submission lag, and data-quality by coverholder and type. Open-breach count comes from vw_authority_breach; binder utilisation from premium vs estimate. Query measures with MEASURE(name).'
WITH METRICS
LANGUAGE YAML
AS $$
version: 0.1

source: lr_serverless_aws_us_catalog.bricksurance_delegated_authority.bordereau_submission

joins:
  - name: binding_authority
    source: lr_serverless_aws_us_catalog.bricksurance_delegated_authority.binding_authority
    on: source.binder_id = binding_authority.binder_id

dimensions:
  - name: bordereau_type_code
    expr: source.bordereau_type_code
  - name: bordereau_status_code
    expr: source.bordereau_status_code
  - name: period_month
    expr: source.period_month
  - name: umr
    expr: binding_authority.umr

measures:
  - name: submission_count
    expr: COUNT(submission_id)
  - name: outstanding_count
    expr: COUNT(CASE WHEN bordereau_status_code IN ('RECEIVED', 'QUARANTINED') THEN submission_id END)
  - name: avg_submission_lag_days
    expr: AVG(datediff(received_date, due_date))
  - name: avg_dq_score
    expr: AVG(dq_score)
$$;
